<?php
/** Listado y visor de documentos normalizados; nunca recibe rutas físicas. */
$documents = is_array($digitalRecord['documents'] ?? null) ? $digitalRecord['documents'] : [];
$archives = is_array($digitalRecord['archives'] ?? null) ? $digitalRecord['archives'] : [];
$package = is_array($digitalRecord['package'] ?? null) ? $digitalRecord['package'] : [];
$canManageFiles = !empty($digitalRecord['can_manage_files']) && !empty($digitalRecord['file_upload']);
$selectableFiles = array_values(array_merge($documents, $archives));
$retirableFiles = array_values(array_filter($selectableFiles, static fn (array $file): bool => empty($file['is_primary']) && empty($file['is_package'])));
$selectedDocument = $selectableFiles[0] ?? null;
$documentGroups = array_filter([
    'Archivo principal' => array_values(array_filter($documents, static fn (array $document): bool => !empty($document['is_primary']) && empty($document['is_package']))),
    'Archivos adicionales' => array_values(array_filter($documents, static fn (array $document): bool => empty($document['is_primary']) && empty($document['is_package']))),
    'Archivos comprimidos adicionales' => $archives,
]);
$visualForExtension = static function (string $extension): array {
    $normalized = mb_strtolower(ltrim(trim($extension), '.'), 'UTF-8');
    return match ($normalized) {
        'pdf' => ['icon' => 'fa-file-pdf', 'label' => 'PDF'],
        'doc', 'docx' => ['icon' => 'fa-file-word', 'label' => mb_strtoupper($normalized, 'UTF-8')],
        'xls', 'xlsx' => ['icon' => 'fa-file-excel', 'label' => mb_strtoupper($normalized, 'UTF-8')],
        'ppt', 'pptx' => ['icon' => 'fa-file-powerpoint', 'label' => mb_strtoupper($normalized, 'UTF-8')],
        'zip' => ['icon' => 'fa-file-zipper', 'label' => 'ZIP'],
        'png', 'jpg', 'jpeg', 'webp' => ['icon' => 'fa-file-image', 'label' => mb_strtoupper($normalized, 'UTF-8')],
        'txt' => ['icon' => 'fa-file-lines', 'label' => 'TXT'],
        default => ['icon' => 'fa-file', 'label' => $normalized !== '' ? mb_strtoupper($normalized, 'UTF-8') : 'ARCHIVO'],
    };
};
