                        <button type="button" role="menuitem" data-file-selection-toggle<?= $retirableFiles ? '' : ' disabled' ?>><i class="fa-solid fa-list-check" aria-hidden="true"></i><span>Seleccionar archivos</span></button>
                    <?php endif; ?>
                </div>
            </div><?php endif; ?>
        </header>
